const { retry } = require('acme-retry');

/**
 * A flaky function that simulates occasional failures
 * Returns a random number, but throws an error 70% of the time
 */
function flakyFunction() {
  const random = Math.random();
  console.log(`Calling flaky function, random value: ${random.toFixed(2)}`);

  if (random < 0.7) {
    throw new Error(`Flaky function failed! Random value ${random.toFixed(2)} < 0.7`);
  }

  return `Success! Got value: ${random.toFixed(2)}`;
}

/**
 * Main example function
 */
async function runExample() {
  console.log('=== acme-retry Example ===\n');
  console.log('Testing a flaky function that fails 70% of the time...\n');

  try {
    // Retry the flaky function up to 5 times with exponential backoff
    const result = await retry(flakyFunction, {
      attempts: 5,
      baseMs: 100  // Base delay of 100ms
    });

    console.log(`\n✅ Final result: ${result}`);
    console.log('\nThe function succeeded after one or more retries!');

  } catch (error) {
    console.log(`\n❌ All retries failed: ${error.message}`);
    console.log('\nThe function failed all 5 attempts.');
  }
}

// Run the example
runExample().catch(console.error);

