/**
 * Example usage of acme-retry package
 */

const { retry } = require('acme-retry');

// Create a flaky function that fails randomly
function flakyFunction() {
  const random = Math.random();

  // Simulate a 70% failure rate
  if (random < 0.7) {
    throw new Error(`Flaky function failed! Random value was: ${random.toFixed(2)}`);
  }

  return `Success! Random value was: ${random.toFixed(2)}`;
}

// Create a more complex flaky function that might work on retry
let callCount = 0;
function flakyCounterFunction() {
  callCount++;

  // First 4 calls will fail, 5th will succeed
  if (callCount < 5) {
    throw new Error(`Flaky counter failed on attempt ${callCount}/5`);
  }

  return `Counter succeeded on attempt ${callCount}!`;
}

// Example 1: Basic retry with 5 attempts
async function example1() {
  console.log('Example 1: Retrying flaky function 5 times');
  console.log('==========================================');

  callCount = 0; // Reset counter

  try {
    const result = await retry(flakyCounterFunction, { attempts: 5, baseMs: 100 });
    console.log(result);
    console.log('Success after retries!\n');
  } catch (error) {
    console.log('Failed after all retries:', error.message, '\n');
  }
}

// Example 2: Retry with custom backoff
async function example2() {
  console.log('Example 2: Retrying with custom base delay (200ms)');
  console.log('==================================================');

  let attemptLog = [];
  function trackedFlakyFunction() {
    const random = Math.random();
    attemptLog.push({ time: new Date().toISOString(), random });

    if (random < 0.9) {
      throw new Error(`Failed with random value: ${random.toFixed(2)}`);
    }

    return `Succeeded with random value: ${random.toFixed(2)}`;
  }

  const startTime = Date.now();
  try {
    const result = await retry(trackedFlakyFunction, { attempts: 5, baseMs: 200 });
    const elapsed = Date.now() - startTime;
    console.log(result);
    console.log(`Total time: ${elapsed}ms`);
    console.log('Attempt log:', attemptLog.map((a, i) => `Attempt ${i+1}: ${a.random.toFixed(2)}`).join(', '), '\n');
  } catch (error) {
    const elapsed = Date.now() - startTime;
    console.log('Failed after all retries:', error.message);
    console.log(`Total time: ${elapsed}ms`);
    console.log('Attempt log:', attemptLog.map((a, i) => `Attempt ${i+1}: ${a.random.toFixed(2)}`).join(', '), '\n');
  }
}

// Example 3: Simulating network request
async function example3() {
  console.log('Example 3: Simulating network request with retry');
  console.log('================================================');

  async function mockNetworkRequest() {
    // Simulate network latency
    await new Promise(resolve => setTimeout(resolve, 50));

    const successRate = 0.4; // 40% success rate
    if (Math.random() > successRate) {
      throw new Error('Network request failed (timeout/500 error)');
    }

    return { data: { id: 123, name: 'Example Data' }, status: 200 };
  }

  try {
    const response = await retry(mockNetworkRequest, { attempts: 5, baseMs: 100 });
    console.log('Network request succeeded:', response);
    console.log('Received data:', response.data, '\n');
  } catch (error) {
    console.log('Network request failed after 5 retries:', error.message, '\n');
  }
}

// Run all examples
async function runExamples() {
  console.log('ACME-RETRY Package Demo');
  console.log('=======================\n');

  await example1();
  await example2();
  await example3();

  console.log('How acme-retry works:');
  console.log('=====================');
  console.log('1. The retry() function accepts a function to execute and optional parameters:');
  console.log('   - attempts: number of retry attempts (default: 3)');
  console.log('   - baseMs: base delay in milliseconds for exponential backoff (default: 100)');
  console.log('\n2. Exponential backoff formula: waitTime = baseMs * 2^attemptNumber');
  console.log('   Where attemptNumber starts at 0 for the first retry.');
  console.log('   Example with baseMs=100: 100ms, 200ms, 400ms, 800ms, 1600ms...');
  console.log('\n3. The function returns a Promise that:');
  console.log('   - Resolves with the successful function result');
  console.log('   - Rejects with the last error after all attempts fail');
  console.log('\n4. Use cases:');
  console.log('   - Network requests that may fail due to temporary issues');
  console.log('   - Database operations that might timeout');
  console.log('   - Any flaky operation that benefits from retries');
}

// Run the examples
runExamples().catch(console.error);

/**
 * Simple example using acme-retry to retry a flaky function 5 times
 */

const { retry } = require('acme-retry');

// A flaky function that has a 60% chance of failing
function flakyAPICall() {
  const random = Math.random();
  console.log(`  Attempting API call... random value: ${random.toFixed(2)}`);

  if (random < 0.6) {
    throw new Error(`API call failed (random: ${random.toFixed(2)})`);
  }

  return { 
    success: true, 
    data: { message: 'API response', value: random.toFixed(2) }
  };
}

async function main() {
  console.log('=== Using acme-retry package ===\n');
  console.log('Flaky API call with 5 retry attempts and exponential backoff\n');
  console.log('Starting retry logic...\n');

  try {
    // Retry the flaky function up to 5 times with 100ms base delay
    const result = await retry(flakyAPICall, { 
      attempts: 5, 
      baseMs: 100 
    });

    console.log('\n✅ Success! Result:', result);
    console.log(`\nThe function succeeded after retries.`);

  } catch (error) {
    console.log('\n❌ All retry attempts failed.');
    console.log(`Final error: ${error.message}`);
  }

  console.log('\n=== How it works ===');
  console.log(`
1. The 'retry' function from acme-retry takes two parameters:
   - The function to execute (must return a Promise or value)
   - Options object with 'attempts' and 'baseMs'

2. With attempts=5 and baseMs=100:
   - 1st attempt: immediate execution
   - 2nd attempt: waits 100ms (100 * 2^0)
   - 3rd attempt: waits 200ms (100 * 2^1) 
   - 4th attempt: waits 400ms (100 * 2^2)
   - 5th attempt: waits 800ms (100 * 2^3)

3. If the function succeeds on any attempt, it returns the result.
4. If all attempts fail, it throws the last error received.

This pattern is useful for:
- Network requests that might time out
- Database operations with transient failures
- External API calls with rate limiting or temporary issues
- Any operation that benefits from "try again with delays"
`);
}

// Run the example
main().catch(console.error);

