/**
 * Example demonstrating the acme-retry package
 * 
 * This example shows how to use the retry function with exponential backoff
 * to handle flaky operations that may fail intermittently.
 */

const { retry } = require('./node_modules/acme-retry');

/**
 * A flaky function that fails randomly for demonstration purposes
 * @param {string} operationName - Name of the operation for logging
 * @param {number} successAfter - After how many attempts should it succeed (default: 3)
 * @returns {Promise<string>} Result message
 */
async function flakyOperation(operationName, successAfter = 3) {
  // Track attempts
  if (!flakyOperation.attemptCount) {
    flakyOperation.attemptCount = 0;
  }
  flakyOperation.attemptCount++;

  console.log(`  Attempt ${flakyOperation.attemptCount} for "${operationName}"...`);

  // Simulate random failure until successAfter attempts
  if (flakyOperation.attemptCount < successAfter) {
    // Simulate different types of errors
    const errors = [
      new Error(`Network timeout for ${operationName}`),
      new Error(`Server error 503 for ${operationName}`),
      new Error(`Database connection failed for ${operationName}`),
      new Error(`Rate limited for ${operationName}`)
    ];
    const randomError = errors[Math.floor(Math.random() * errors.length)];
    throw randomError;
  }

  // Success case
  const result = `Successfully completed "${operationName}" on attempt ${flakyOperation.attemptCount}`;
  console.log(`  ✓ ${result}`);
  flakyOperation.attemptCount = 0; // Reset for next call
  return result;
}

/**
 * Main demonstration function
 */
async function demonstrateRetry() {
  console.log('=== ACME-RETRY DEMONSTRATION ===\n');

  // Example 1: Basic usage with default options (3 attempts, 100ms base)
  console.log('Example 1: Basic usage (default: 3 attempts)');
  console.log('Calling flaky operation that will succeed on 3rd attempt...');

  try {
    const result1 = await retry(() => flakyOperation("Basic API Call", 3));
    console.log(`Result: ${result1}\n`);
  } catch (error) {
    console.log(`Error: ${error.message}\n`);
  }

  // Example 2: Custom retry configuration (5 attempts, 200ms base)
  console.log('Example 2: Custom configuration (5 attempts, 200ms base)');
  console.log('Calling flaky operation that will succeed on 5th attempt...');

  try {
    const result2 = await retry(
      () => flakyOperation("Database Query", 5),
      { attempts: 5, baseMs: 200 }
    );
    console.log(`Result: ${result2}\n`);
  } catch (error) {
    console.log(`Error: ${error.message}\n`);
  }

  // Example 3: Operation that always fails (exceeds retry attempts)
  console.log('Example 3: Operation that always fails (exceeds 5 retry attempts)');
  console.log('Calling flaky operation that needs 10 attempts but we only allow 5...');

  try {
    const result3 = await retry(
