      throw new Error(`API request failed for user ${userId}`);
    }
    return `User data for ${userId}: {id: ${userId}, name: "John Doe"}`;
  }

  // Try to fetch user data with retry logic
  try {
    const userData = await retry(
      () => fetchUserData(123),
      { attempts: 5, baseMs: 150 }
    );
    console.log(`✓ ${userData}\n`);
  } catch (error) {
    console.log(`✗ Failed to fetch user data: ${error.message}\n`);
  }

  // Show timing example
  console.log('=== TIMING EXPLANATION ===');
  console.log('With baseMs=100 and attempts=5, the retry pattern is:');
  console.log('  Attempt 1: Immediate');
  console.log('  Attempt 2: Wait 100ms (100 * 2^0)');
  console.log('  Attempt 3: Wait 200ms (100 * 2^1)');
  console.log('  Attempt 4: Wait 400ms (100 * 2^2)');
  console.log('  Attempt 5: Wait 800ms (100 * 2^3)');
  console.log('\nThis exponential backoff helps prevent overwhelming');
  console.log('the service while giving it time to recover.');
