const flakyFunction = () => {
  attemptNumber++;
  console.log(`[Attempt ${attemptNumber}] Executing function...`);

  // Simulate random failure (60% chance of failure)
  if (Math.random() < 0.6) {
    throw new Error(`Function failed on attempt ${attemptNumber}`);
  }

  return `Success after ${attemptNumber} attempts! Data: ${Math.random().toFixed(3)}`;
};

async function main() {
  console.log('Starting 5 retry attempts with exponential backoff...\n');

  // Reset counter
