    });

    console.log(`\n🎉 Final result: ${result}`);

  } catch (error) {
    console.log(`\n💥 All 5 attempts failed. Last error: ${error.message}`);
  }

  console.log('\n--- How it works ---');
  console.log('The retry function:');
  console.log('1. Attempts to execute your function immediately');
  console.log('2. If it fails, waits for baseMs × 2^(attempt-1) milliseconds');
  console.log('3. Retries up to the specified number of attempts (5 in this case)');
  console.log('4. Returns the successful result or throws the last error');
  console.log('\nDelay progression with baseMs=100:');
  console.log('• Attempt 1 → No delay (initial try)');
  console.log('• Attempt 2 → 100ms delay (100 × 2^0)');
  console.log('• Attempt 3 → 200ms delay (100 × 2^1)');
