    console.error(`Last error: ${error.message}`);
    console.log(`Total calls attempted: ${callCount}`);
  }

  console.log('\n=== How it works ===');
  console.log(`
  1. The retry() function takes your flaky function and options
  2. It calls your function and waits for the result
  3. If it fails (throws an error), it waits with exponential backoff:
     - Attempt 1 → 100ms delay
     - Attempt 2 → 200ms delay (100 * 2^1)
     - Attempt 3 → 400ms delay (100 * 2^2)
     - Attempt 4 → 800ms delay (100 * 2^3)
     - Attempt 5 → 1600ms delay (100 * 2^4)
  4. If successful at any point, it returns the result immediately
  5. If all attempts fail, it throws the last error

  This pattern is especially useful for:
  - Network requests that might timeout
  - Database connections that might be temporarily unavailable
  - External API calls that might rate limit
  - Any operation with transient failures
  `);
}

// Run the example
main();

