/**
 * Real-world example: Retrying API calls with acme-retry
 */

const { retry } = require('acme-retry');

// Simulate an API client with retry logic
class ApiClient {
  constructor() {
    this.requestCount = 0;
  }

  // Simulate an unreliable API call
  async fetchUserData(userId) {
    this.requestCount++;
    console.log(`[API Request #${this.requestCount}] Fetching user ${userId}...`);

    // Simulate various failure modes
    const random = Math.random();

    if (random < 0.1) {
      throw new Error('Network timeout');
    } else if (random < 0.3) {
      throw new Error('Server error 503 - Service Unavailable');
    } else if (random < 0.4) {
      throw new Error('Rate limited - Try again later');
    } else if (random < 0.45) {
      throw new Error('Gateway timeout');
    }

    // Success case
    await new Promise(resolve => setTimeout(resolve, 50)); // Simulate network delay
    return {
      userId,
      name: 'John Doe',
      email: 'john@example.com',
      requestAttempt: this.requestCount
    };
  }

  // Wrapper method with retry logic
  async fetchUserDataWithRetry(userId, maxAttempts = 5) {
    console.log(`\n🔧 Attempting to fetch user ${userId} with ${maxAttempts} retries`);

    try {
      const result = await retry(
        () => this.fetchUserData(userId),
        {
          attempts: maxAttempts,
          baseMs: 200 // Start with 200ms, then 400ms, 800ms, 1.6s, 3.2s
        }
      );

      console.log(`✅ Success after ${this.requestCount} attempt(s)`);
      return result;

    } catch (error) {
      console.error(`❌ Failed after ${maxAttempts} attempts: ${error.message}`);
      throw error;
    }
  }
}

// Simulate different scenarios
async function simulateApiCalls() {
  const client = new ApiClient();

  console.log('=== Real-World API Retry Example ===\n');

  // Scenario 1: Successful on first try
  console.log('Scenario 1: Successful on first try');
  console.log('-----------------------------------');
  try {
    const user1 = await client.fetchUserDataWithRetry(123, 3);
    console.log('User data:', user1);
  } catch (error) {
    console.log('(This should succeed)');
  }

  // Reset counter for next scenario
  client.requestCount = 0;

  // Scenario 2: Succeeds after a few retries  
  console.log('\n\nScenario 2: Succeeds after retries');
  console.log('----------------------------------');
  // We'll simulate this by temporarily modifying the random threshold
  const originalRandom = Math.random;
  let callNum = 0;
  Math.random = () => {
    callNum++;
    // Fail first 2 calls, succeed on 3rd
    return callNum < 3 ? 0.2 : 0.9;
  };

  try {
    const user2 = await client.fetchUserDataWithRetry(456, 5);
    console.log('User data:', user2);
  } catch (error) {
    console.log('(This should also succeed after retries)');
  }

  // Restore original Math.random
  Math.random = originalRandom;

  // Scenario 3: All retries fail
  console.log('\n\nScenario 3: All retries fail');
  console.log('----------------------------');
  client.requestCount = 0;

  // Force all failures
  Math.random = () => 0.1; // Always below 0.1 threshold for network timeout

  try {
    await client.fetchUserDataWithRetry(789, 3);
  } catch (error) {
    console.log(`Correctly caught error: ${error.message}`);
  }

  // Restore original
  Math.random = originalRandom;

  console.log('\n\n=== Key Takeaways ===');
  console.log(`
  1. The acme-retry package makes it easy to add resilience to API calls
  2. Exponential backoff prevents overwhelming failing services
  3. Works well for transient errors (network issues, rate limits, etc.)
  4. Simple configuration: just specify attempts and base delay
  5. Realistic delays: 200ms, 400ms, 800ms, 1.6s, 3.2s for 5 attempts
  6. Clean error handling when all retries are exhausted

  This pattern is essential for building robust distributed systems
  that can handle temporary infrastructure issues gracefully.
  `);
}

// Run the simulation
simulateApiCalls().catch(console.error);
